  ('abdominal', 1, 'published', '{"schemaVersion":1,"id":"abdominal","title":"Mal au ventre","subtitle":"Douleur, crampes, nausée ou trouble digestif","iconKey":"stomach","colorHex":"#F29D49","questions":[{"id":"abdominal_onset","title":"Début du malaise","prompt":"Depuis quand avez-vous mal au ventre ?","iconKey":"clock","requiredTags":[],"excludedTags":[],"options":[{"id":"sudden","label":"Très soudainement","iconKey":"choice","tags":["sudden"],"urgency":"consultationToday","nextQuestionId":null},{"id":"hours","label":"Depuis quelques heures","iconKey":"clock","tags":["acute"],"urgency":"selfCare","nextQuestionId":null},{"id":"days","label":"Depuis plusieurs jours","iconKey":"calendar","tags":["persistent"],"urgency":"consultationSoon","nextQuestionId":null},{"id":"recurrent","label":"Cela revient régulièrement","iconKey":"choice","tags":["recurrent"],"urgency":"consultationSoon","nextQuestionId":null}]},{"id":"abdominal_location","title":"Zone douloureuse","prompt":"Où ressentez-vous surtout la douleur ?","iconKey":"choice","requiredTags":[],"excludedTags":[],"options":[{"id":"upper","label":"En haut ou après les repas","iconKey":"choice","tags":["after_meal","upper_abdomen"],"urgency":"selfCare","nextQuestionId":null},{"id":"lower_right","label":"En bas à droite","iconKey":"choice","tags":["lower_right"],"urgency":"consultationToday","nextQuestionId":null},{"id":"lower","label":"Dans le bas-ventre","iconKey":"choice","tags":["lower_abdomen"],"urgency":"selfCare","nextQuestionId":null},{"id":"diffuse","label":"Partout ou en crampes","iconKey":"choice","tags":["cramps","diffuse"],"urgency":"selfCare","nextQuestionId":null}]},{"id":"abdominal_intensity","title":"Intensité","prompt":"Quelle est l’intensité de la douleur maintenant ?","iconKey":"choice","requiredTags":[],"excludedTags":[],"options":[{"id":"mild","label":"Légère, je fonctionne normalement","iconKey":"choice","tags":["mild_pain"],"urgency":"selfCare","nextQuestionId":null},{"id":"moderate","label":"Modérée, elle me gêne","iconKey":"choice","tags":["moderate_pain"],"urgency":"consultationSoon","nextQuestionId":null},{"id":"severe","label":"Très forte ou insupportable","iconKey":"alert","tags":["severe_pain"],"urgency":"emergency","nextQuestionId":null},{"id":"rigid","label":"Ventre dur ou très douloureux au toucher","iconKey":"choice","tags":["rigid_abdomen","severe_pain"],"urgency":"emergency","nextQuestionId":null}]},{"id":"abdominal_associated","title":"Autres signes","prompt":"Quel autre signe accompagne le mieux la douleur ?","iconKey":"choice","requiredTags":[],"excludedTags":[],"options":[{"id":"none","label":"Aucun de ceux-ci","iconKey":"choice","tags":["isolated_pain"],"urgency":"selfCare","nextQuestionId":null},{"id":"vomit_diarrhea","label":"Vomissements ou diarrhée","iconKey":"blood","tags":["diarrhea","vomiting"],"urgency":"selfCare","nextQuestionId":null},{"id":"fever","label":"Fièvre ou frissons","iconKey":"temperature","tags":["fever"],"urgency":"consultationToday","nextQuestionId":null},{"id":"blood","label":"Sang vomi, selles sanglantes ou noires","iconKey":"emergency","tags":["bleeding","digestive_bleeding"],"urgency":"emergency","nextQuestionId":null}]},{"id":"abdominal_drink","title":"Hydratation","prompt":"Arrivez-vous à boire et à garder les liquides ?","iconKey":"water","requiredTags":[],"excludedTags":[],"options":[{"id":"yes","label":"Oui, normalement","iconKey":"check","tags":["hydrated"],"urgency":"selfCare","nextQuestionId":null},{"id":"little","label":"Un peu seulement","iconKey":"choice","tags":["dehydration_risk"],"urgency":"consultationToday","nextQuestionId":null},{"id":"no","label":"Non, je vomis tout ou je suis très faible","iconKey":"alert","tags":["cannot_hydrate","dehydration_risk"],"urgency":"emergency","nextQuestionId":null}]},{"id":"abdominal_context","title":"Contexte important","prompt":"L’une de ces situations vous concerne-t-elle ?","iconKey":"info","requiredTags":[],"excludedTags":[],"options":[{"id":"urinary","label":"Douleur ou brûlure en urinant","iconKey":"choice","tags":["urinary"],"urgency":"consultationToday","nextQuestionId":null},{"id":"pregnancy","label":"Grossesse possible ou confirmée","iconKey":"pregnancy","tags":["pregnancy_possible"],"urgency":"consultationToday","nextQuestionId":null},{"id":"collapse","label":"Malaise, confusion ou perte de connaissance","iconKey":"choice","tags":["collapse"],"urgency":"emergency","nextQuestionId":null},{"id":"none","label":"Aucune de ces situations","iconKey":"check","tags":[],"urgency":"selfCare","nextQuestionId":null}]}],"possibilities":[{"title":"Gastro-entérite ou irritation digestive","explanation":"Des crampes avec diarrhée ou vomissements sont compatibles avec une irritation ou une infection digestive.","tagWeights":{"diarrhea":28,"vomiting":22,"diffuse":12,"acute":8},"baseScore":8},{"title":"Appendicite possible","explanation":"Une douleur en bas à droite, surtout avec fièvre ou nausée, nécessite un examen médical rapide.","tagWeights":{"lower_right":42,"fever":25,"vomiting":15,"severe_pain":12},"baseScore":8},{"title":"Reflux, gastrite ou indigestion","explanation":"Une gêne du haut du ventre liée aux repas peut correspondre à une irritation gastrique.","tagWeights":{"upper_abdomen":30,"after_meal":24,"recurrent":12,"mild_pain":6},"baseScore":8},{"title":"Problème urinaire ou calcul","explanation":"La douleur abdominale associée à une gêne urinaire peut venir des voies urinaires.","tagWeights":{"urinary":42,"lower_abdomen":18,"fever":16,"severe_pain":10},"baseScore":8}],"selfCare":["Buvez régulièrement de petites quantités d’eau ou de solution de réhydratation.","Choisissez des aliments simples si vous pouvez manger et évitez l’alcool."],"pharmacyAdvice":["Une solution de réhydratation orale peut aider en cas de diarrhée ou de vomissements légers.","Demandez conseil au pharmacien avant un antidouleur; certains anti-inflammatoires peuvent irriter l’estomac."]}'::jsonb, 'Catalogue initial validé', CURRENT_TIMESTAMP),
  ('headache', 1, 'published', '{"schemaVersion":1,"id":"headache","title":"Migraine ou mal de tête","subtitle":"Douleur à la tête, lumière gênante ou nausée","iconKey":"head","colorHex":"#7759D8","questions":[{"id":"headache_onset","title":"Apparition","prompt":"Comment ce mal de tête a-t-il commencé ?","iconKey":"choice","requiredTags":[],"excludedTags":[],"options":[{"id":"thunderclap","label":"Brutalement, le pire de ma vie","iconKey":"emergency","tags":["severe_headache","thunderclap"],"urgency":"emergency","nextQuestionId":null},{"id":"gradual","label":"Progressivement aujourd’hui","iconKey":"choice","tags":["gradual"],"urgency":"selfCare","nextQuestionId":null},{"id":"days","label":"Depuis plusieurs jours","iconKey":"calendar","tags":["persistent"],"urgency":"consultationSoon","nextQuestionId":null},{"id":"usual","label":"C’est similaire à mes crises habituelles","iconKey":"choice","tags":["recurrent","usual_pattern"],"urgency":"selfCare","nextQuestionId":null}]},{"id":"headache_pattern","title":"Type de douleur","prompt":"Quelle description correspond le mieux ?","iconKey":"choice","requiredTags":[],"excludedTags":[],"options":[{"id":"one_side","label":"D’un côté et pulsatile","iconKey":"choice","tags":["one_sided","pulsating"],"urgency":"selfCare","nextQuestionId":null},{"id":"band","label":"Comme un bandeau ou une pression","iconKey":"choice","tags":["bilateral","pressure"],"urgency":"selfCare","nextQuestionId":null},{"id":"face","label":"Front ou visage avec nez bouché","iconKey":"face","tags":["congestion","facial_pressure"],"urgency":"selfCare","nextQuestionId":null},{"id":"general","label":"Diffuse, difficile à décrire","iconKey":"choice","tags":["diffuse"],"urgency":"selfCare","nextQuestionId":null}]},{"id":"headache_associated","title":"Signes associés","prompt":"Qu’est-ce qui accompagne surtout la douleur ?","iconKey":"choice","requiredTags":[],"excludedTags":[],"options":[{"id":"light_nausea","label":"Lumière ou bruit gênant, avec nausée","iconKey":"choice","tags":["nausea","photophobia"],"urgency":"selfCare","nextQuestionId":null},{"id":"neck_tension","label":"Tension du cou, fatigue ou stress","iconKey":"choice","tags":["neck_tension","stress"],"urgency":"selfCare","nextQuestionId":null},{"id":"fever_stiff","label":"Fièvre, nuque raide ou éruption inhabituelle","iconKey":"emergency","tags":["fever","severe_headache","stiff_neck"],"urgency":"emergency","nextQuestionId":null},{"id":"none","label":"Aucun de ceux-ci","iconKey":"choice","tags":[],"urgency":"selfCare","nextQuestionId":null}]},{"id":"headache_neuro","title":"Signes neurologiques","prompt":"Avez-vous remarqué l’un de ces signes ?","iconKey":"head","requiredTags":[],"excludedTags":[],"options":[{"id":"weakness","label":"Faiblesse d’un côté ou difficulté à parler","iconKey":"emergency","tags":["neurologic_deficit"],"urgency":"emergency","nextQuestionId":null},{"id":"confusion","label":"Confusion, convulsion ou évanouissement","iconKey":"choice","tags":["confusion","seizure"],"urgency":"emergency","nextQuestionId":null},{"id":"vision","label":"Vision trouble nouvelle ou persistante","iconKey":"choice","tags":["vision_change"],"urgency":"consultationToday","nextQuestionId":null},{"id":"none","label":"Aucun de ces signes","iconKey":"check","tags":[],"urgency":"selfCare","nextQuestionId":null}]},{"id":"headache_context","title":"Contexte","prompt":"Quelle situation s’applique ?","iconKey":"choice","requiredTags":[],"excludedTags":[],"options":[{"id":"injury","label":"Après un choc à la tête","iconKey":"choice","tags":["head_injury"],"urgency":"consultationToday","nextQuestionId":null},{"id":"pregnant","label":"Enceinte ou récemment accouchée","iconKey":"pregnancy","tags":["pregnancy_possible","severe_headache"],"urgency":"consultationToday","nextQuestionId":null},{"id":"dehydrated","label":"Peu bu, chaleur ou repas sauté","iconKey":"water","tags":["dehydration_risk"],"urgency":"selfCare","nextQuestionId":null},{"id":"none","label":"Aucune de ces situations","iconKey":"check","tags":[],"urgency":"selfCare","nextQuestionId":null}]}],"possibilities":[{"title":"Migraine","explanation":"Une douleur pulsatile d’un côté avec gêne à la lumière, au bruit ou nausée est compatible avec une migraine.","tagWeights":{"one_sided":25,"pulsating":24,"photophobia":25,"nausea":18,"usual_pattern":10},"baseScore":8},{"title":"Céphalée de tension","explanation":"Une pression en bandeau avec tension du cou ou stress peut correspondre à une céphalée de tension.","tagWeights":{"pressure":30,"bilateral":18,"neck_tension":26,"stress":18},"baseScore":8},{"title":"Céphalée liée à une congestion","explanation":"Une pression du visage avec nez bouché peut accompagner une infection respiratoire ou une inflammation des sinus.","tagWeights":{"facial_pressure":32,"congestion":32,"fever":10},"baseScore":8},{"title":"Déshydratation ou fatigue","explanation":"Le manque d’eau, la chaleur, le manque de sommeil ou un repas sauté peuvent favoriser un mal de tête.","tagWeights":{"dehydration_risk":42,"gradual":12,"diffuse":12},"baseScore":8}],"selfCare":["Reposez-vous dans un endroit calme et sombre, hydratez-vous et évitez les écrans si cela aggrave la douleur.","Notez le début, la durée et les déclencheurs pour en parler lors d’une consultation."],"pharmacyAdvice":["Le paracétamol peut parfois soulager un mal de tête léger; suivez strictement l’étiquette et évitez de cumuler des produits qui en contiennent.","Demandez au pharmacien avant un anti-inflammatoire si vous avez un ulcère, une maladie rénale, prenez un anticoagulant ou pourriez être enceinte."]}'::jsonb, 'Catalogue initial validé', CURRENT_TIMESTAMP),
  ('menstrual', 1, 'published', '{"schemaVersion":1,"id":"menstrual","title":"Santé menstruelle","subtitle":"Règles douloureuses, irrégulières ou saignement","iconKey":"blood","colorHex":"#E65F91","questions":[{"id":"menstrual_concern","title":"Malaise principal","prompt":"Qu’est-ce qui vous préoccupe le plus ?","iconKey":"heart","requiredTags":[],"excludedTags":[],"options":[{"id":"pain","label":"Douleurs ou crampes","iconKey":"choice","tags":["cramps"],"urgency":"selfCare","nextQuestionId":null},{"id":"heavy","label":"Saignement plus abondant","iconKey":"blood","tags":["heavy_bleeding"],"urgency":"consultationSoon","nextQuestionId":null},{"id":"irregular","label":"Règles irrégulières ou absentes","iconKey":"choice","tags":["irregular_cycle"],"urgency":"selfCare","nextQuestionId":null},{"id":"discharge","label":"Pertes inhabituelles ou irritation","iconKey":"info","tags":["discharge"],"urgency":"consultationSoon","nextQuestionId":null}]},{"id":"menstrual_severity","title":"Intensité","prompt":"Quelle situation correspond le mieux ?","iconKey":"choice","requiredTags":[],"excludedTags":[],"options":[{"id":"manageable","label":"Gênant mais supportable","iconKey":"choice","tags":["mild_pain"],"urgency":"selfCare","nextQuestionId":null},{"id":"limits","label":"M’empêche de travailler ou dormir","iconKey":"choice","tags":["activity_limiting","moderate_pain"],"urgency":"consultationSoon","nextQuestionId":null},{"id":"severe","label":"Douleur brutale ou insupportable","iconKey":"alert","tags":["severe_pain"],"urgency":"emergency","nextQuestionId":null},{"id":"very_heavy","label":"Une protection saturée par heure pendant 2 heures","iconKey":"emergency","tags":["bleeding","very_heavy_bleeding"],"urgency":"emergency","nextQuestionId":null}]},{"id":"menstrual_associated","title":"Autres signes","prompt":"Avez-vous l’un de ces signes ?","iconKey":"choice","requiredTags":[],"excludedTags":[],"options":[{"id":"dizzy","label":"Vertiges, faiblesse ou évanouissement","iconKey":"choice","tags":["collapse","dizziness"],"urgency":"emergency","nextQuestionId":null},{"id":"fever","label":"Fièvre, mauvaise odeur ou forte douleur pelvienne","iconKey":"temperature","tags":["discharge","fever","pelvic_pain"],"urgency":"consultationToday","nextQuestionId":null},{"id":"chronic","label":"Douleur pendant les rapports ou depuis plusieurs cycles","iconKey":"choice","tags":["chronic_pelvic_pain","recurrent"],"urgency":"consultationSoon","nextQuestionId":null},{"id":"none","label":"Aucun de ces signes","iconKey":"check","tags":[],"urgency":"selfCare","nextQuestionId":null}]},{"id":"menstrual_pregnancy","title":"Possibilité de grossesse","prompt":"Une grossesse est-elle possible ?","iconKey":"pregnancy","requiredTags":[],"excludedTags":[],"options":[{"id":"yes_bleeding","label":"Oui, avec douleur ou saignement","iconKey":"emergency","tags":["bleeding","pelvic_pain","pregnancy_possible"],"urgency":"emergency","nextQuestionId":null},{"id":"yes_no_bleeding","label":"Oui, sans douleur forte ni saignement","iconKey":"choice","tags":["missed_period","pregnancy_possible"],"urgency":"consultationSoon","nextQuestionId":null},{"id":"no","label":"Non","iconKey":"choice","tags":[],"urgency":"selfCare","nextQuestionId":null},{"id":"unsure","label":"Je ne sais pas","iconKey":"choice","tags":["pregnancy_possible"],"urgency":"consultationSoon","nextQuestionId":null}]},{"id":"menstrual_change","title":"Évolution","prompt":"Depuis combien de temps ce changement existe-t-il ?","iconKey":"calendar","requiredTags":[],"excludedTags":[],"options":[{"id":"first","label":"C’est la première fois","iconKey":"choice","tags":["new_pattern"],"urgency":"selfCare","nextQuestionId":null},{"id":"few_cycles","label":"Depuis 2 ou 3 cycles","iconKey":"calendar","tags":["persistent"],"urgency":"consultationSoon","nextQuestionId":null},{"id":"long","label":"Depuis longtemps","iconKey":"choice","tags":["chronic","recurrent"],"urgency":"consultationSoon","nextQuestionId":null}]}],"possibilities":[{"title":"Dysménorrhée (règles douloureuses)","explanation":"Des crampes liées aux règles, sans signe d’alerte, sont compatibles avec des règles douloureuses.","tagWeights":{"cramps":38,"mild_pain":16,"moderate_pain":18,"recurrent":12},"baseScore":8},{"title":"Saignement menstruel abondant","explanation":"Un flux nettement plus important peut nécessiter un bilan, notamment pour rechercher une anémie ou une cause gynécologique.","tagWeights":{"heavy_bleeding":38,"very_heavy_bleeding":40,"dizziness":18,"persistent":10},"baseScore":8},{"title":"Cycle irrégulier ou cause hormonale","explanation":"Des règles retardées, absentes ou variables peuvent avoir plusieurs causes, dont le stress, une grossesse ou un changement hormonal.","tagWeights":{"irregular_cycle":44,"missed_period":28,"persistent":12},"baseScore":8},{"title":"Infection ou inflammation pelvienne possible","explanation":"Des pertes inhabituelles avec fièvre ou douleur pelvienne doivent être évaluées rapidement.","tagWeights":{"discharge":28,"fever":28,"pelvic_pain":26},"baseScore":8},{"title":"Endométriose ou autre cause gynécologique possible","explanation":"Une douleur qui limite les activités, revient sur plusieurs cycles ou survient pendant les rapports mérite un bilan.","tagWeights":{"chronic_pelvic_pain":35,"activity_limiting":25,"recurrent":18,"chronic":12},"baseScore":8}],"selfCare":["Une bouillotte tiède et un repos adapté peuvent soulager des crampes légères.","Notez les jours, le flux et les symptômes dans le suivi de cycle."],"pharmacyAdvice":["Demandez au pharmacien quel antidouleur est compatible avec vos antécédents et traitements.","Évitez l’aspirine en cas de saignement important et demandez un avis si une grossesse est possible."]}'::jsonb, 'Catalogue initial validé', CURRENT_TIMESTAMP),
  ('respiratory', 1, 'published', '{"schemaVersion":1,"id":"respiratory","title":"Santé respiratoire","subtitle":"Toux, congestion, respiration sifflante ou essoufflement","iconKey":"air","colorHex":"#149D9A","questions":[{"id":"respiratory_breathing","title":"Respiration maintenant","prompt":"Comment respirez-vous en ce moment ?","iconKey":"air","requiredTags":[],"excludedTags":[],"options":[{"id":"normal","label":"Normalement malgré la toux ou le nez bouché","iconKey":"check","tags":["breathing_ok"],"urgency":"selfCare","nextQuestionId":null},{"id":"mild","label":"Un peu essoufflé(e), je parle normalement","iconKey":"choice","tags":["mild_breathlessness"],"urgency":"consultationSoon","nextQuestionId":null},{"id":"severe","label":"Trop essoufflé(e) pour parler en phrases","iconKey":"emergency","tags":["severe_breathlessness"],"urgency":"emergency","nextQuestionId":null},{"id":"blue","label":"Lèvres bleues/grises, confusion ou épuisement","iconKey":"emergency","tags":["confusion","cyanosis"],"urgency":"emergency","nextQuestionId":null}]},{"id":"respiratory_main","title":"Signe principal","prompt":"Quel signe correspond le mieux ?","iconKey":"info","requiredTags":[],"excludedTags":[],"options":[{"id":"dry_cough","label":"Toux sèche ou gorge irritée","iconKey":"choice","tags":["dry_cough"],"urgency":"selfCare","nextQuestionId":null},{"id":"wet_cough","label":"Toux avec crachats","iconKey":"blood","tags":["productive_cough"],"urgency":"selfCare","nextQuestionId":null},{"id":"wheeze","label":"Sifflement ou oppression","iconKey":"choice","tags":["chest_tightness","wheeze"],"urgency":"consultationToday","nextQuestionId":null},{"id":"nose","label":"Nez bouché, éternuements ou gorge","iconKey":"face","tags":["congestion","upper_respiratory"],"urgency":"selfCare","nextQuestionId":null}]},{"id":"respiratory_red_flags","title":"Signes d’alerte","prompt":"Avez-vous l’un de ces signes ?","iconKey":"alert","requiredTags":[],"excludedTags":[],"options":[{"id":"chest_pain","label":