gs":[],"urgency":"selfCare","nextQuestionId":null}]}],"possibilities":[{"title":"Infection respiratoire virale","explanation":"Toux, nez bouché, gorge irritée et contact malade sont compatibles avec une infection virale fréquente.","tagWeights":{"dry_cough":20,"congestion":24,"upper_respiratory":20,"sick_contact":20,"days":8},"baseScore":8},{"title":"Asthme ou bronchospasme possible","explanation":"Un sifflement et une oppression, surtout avec un antécédent d’asthme, doivent être évalués.","tagWeights":{"wheeze":34,"chest_tightness":28,"asthma_history":30,"allergen_trigger":12},"baseScore":8},{"title":"Pneumonie ou infection basse possible","explanation":"Une toux avec fièvre, faiblesse ou essoufflement peut nécessiter un examen des poumons.","tagWeights":{"productive_cough":22,"fever":28,"systemically_unwell":22,"mild_breathlessness":16,"worsening":10},"baseScore":8},{"title":"Allergie respiratoire","explanation":"Éternuements, congestion ou sifflement après un déclencheur peuvent correspondre à une réaction allergique.","tagWeights":{"allergen_trigger":38,"congestion":22,"wheeze":20},"baseScore":8}],"selfCare":["Reposez-vous, buvez régulièrement et évitez fumée, poussière et parfums irritants.","Portez un masque si une infection transmissible est possible et aérez les espaces."],"pharmacyAdvice":["Une solution saline nasale peut aider pour une congestion simple.","N’utilisez pas l’antibiotique ou l’inhalateur d’une autre personne; demandez conseil à un professionnel."]}'::jsonb, 'Catalogue initial validé', CURRENT_TIMESTAMP),
